1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.5rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	  }
27	  button {
28	    padding: 0.5rem 1rem;
29	    font: inherit;
30	    border: 0;
31	    border-radius: 6px;
32	    background: #1c1917;
33	    color: #fff;
34	    cursor: pointer;
35	  }
36	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
37	  li {
38	    display: flex;
39	    align-items: center;
40	    gap: 0.5rem;
41	    padding: 0.5rem 0.75rem;
42	    margin-bottom: 0.5rem;
43	    background: #fff;
44	    border: 1px solid #e7e5e4;
45	    border-radius: 6px;
46	  }
47	  li span { flex: 1; overflow-wrap: anywhere; }
48	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
49	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
50	  li[data-completed="true"] span { text-decoration: line-through; color: #78716c; }
51	  form input[type="date"] { flex: none; }
52	  .due { flex: none; font-size: 0.875rem; color: #57534e; }
53	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
54	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
55	  form select { flex: none; padding: 0.5rem; font: inherit; border: 1px solid #d6d3d1; border-radius: 6px; background: #fff; }
56	  li[data-priority] { border-left-width: 4px; }
57	  li[data-priority="high"] { border-left-color: #dc2626; }
58	  li[data-priority="med"] { border-left-color: #f59e0b; }
59	  li[data-priority="low"] { border-left-color: #a8a29e; }
60	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
61	  .filters button { background: #e7e5e4; color: #1c1917; padding: 0.25rem 0.75rem; }
62	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; }
63	</style>
64	</head>
65	<body>
66	<main>
67	  <h1>Todos</h1>
68	  <form id="add-form">
69	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
70	    <input data-testid="todo-due" type="date" aria-label="Due date">
71	    <select data-testid="todo-priority" aria-label="Priority">
72	      <option value="low">Low</option>
73	      <option value="med" selected>Med</option>
74	      <option value="high">High</option>
75	    </select>
76	    <button data-testid="todo-add" type="submit">Add</button>
77	  </form>
78	  <div class="filters" role="group" aria-label="Filter todos">
79	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
80	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
81	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
82	  </div>
83	  <ul data-testid="todo-list"></ul>
84	</main>
85	<script src="todo-logic.js"></script>
86	<script>
87	(function () {
88	  var STORAGE_KEY = 'todos';
89	  var form = document.getElementById('add-form');
90	  var input = document.querySelector('[data-testid="todo-input"]');
91	  var dueInput = document.querySelector('[data-testid="todo-due"]');
92	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
93	  var list = document.querySelector('[data-testid="todo-list"]');
94	
95	  function load() {
96	    try {
97	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
98	      return Array.isArray(data) ? data : [];
99	    } catch (e) {
100	      return [];
101	    }
102	  }
103	
104	  function save() {
105	    try {
106	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
107	    } catch (e) {}
108	  }
109	
110	  function newId() {
111	    if (window.crypto && typeof crypto.randomUUID === 'function') {
112	      return crypto.randomUUID();
113	    }
114	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
115	  }
116	
117	  function render() {
118	    renderedDay = TodoLogic.localToday();
119	    list.textContent = '';
120	    filterButtons.forEach(function (btn) {
121	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === filter));
122	    });
123	    TodoLogic.visibleTodos(todos, filter).forEach(function (todo) {
124	      var li = document.createElement('li');
125	      li.setAttribute('data-testid', 'todo-item');
126	      li.dataset.id = todo.id;
127	      li.setAttribute('data-completed', String(!!todo.completed));
128	      li.setAttribute('data-overdue', String(TodoLogic.isOverdue(todo, renderedDay)));
129	      li.setAttribute('data-priority', TodoLogic.normalizePriority(todo.priority));
130	
131	      var toggle = document.createElement('input');
132	      toggle.type = 'checkbox';
133	      toggle.setAttribute('data-testid', 'todo-toggle');
134	      toggle.setAttribute('aria-label', 'Mark complete');
135	      toggle.checked = !!todo.completed;
136	      toggle.addEventListener('change', function () {
137	        todo.completed = toggle.checked;
138	        save();
139	        render();
140	      });
141	
142	      var text = document.createElement('span');
143	      text.setAttribute('data-testid', 'todo-text');
144	      text.textContent = todo.text;
145	
146	      var del = document.createElement('button');
147	      del.type = 'button';
148	      del.setAttribute('data-testid', 'todo-delete');
149	      del.setAttribute('aria-label', 'Delete');
150	      del.textContent = 'Delete';
151	      del.addEventListener('click', function () {
152	        todos = todos.filter(function (t) { return t.id !== todo.id; });
153	        save();
154	        render();
155	      });
156	
157	      li.appendChild(toggle);
158	      li.appendChild(text);
159	      if (todo.due) {
160	        var due = document.createElement('span');
161	        due.className = 'due';
162	        due.setAttribute('data-testid', 'todo-due-label');
163	        due.textContent = 'Due ' + todo.due;
164	        li.appendChild(due);
165	      }
166	      li.appendChild(del);
167	      list.appendChild(li);
168	    });
169	  }
170	
171	  var todos = load();
172	  var filter = 'all';
173	  var renderedDay = '';
174	  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('[data-filter]'));
175	
176	  filterButtons.forEach(function (btn) {
177	    btn.addEventListener('click', function () {
178	      filter = btn.dataset.filter;
179	      render();
180	    });
181	  });
182	
183	  form.addEventListener('submit', function (event) {
184	    event.preventDefault();
185	    var text = input.value.trim();
186	    if (!text) return;
187	    var todo = {
188	      id: newId(), text: text, createdAt: Date.now(), completed: false,
189	      priority: TodoLogic.normalizePriority(priorityInput.value)
190	    };
191	    if (/^\d{4}-\d{2}-\d{2}$/.test(dueInput.value)) todo.due = dueInput.value;
192	    todos.push(todo);
193	    save();
194	    render();
195	    input.value = '';
196	    dueInput.value = '';
197	    priorityInput.value = 'med';
198	    input.focus();
199	  });
200	
201	  // Re-render when the local day changes so overdue flags stay current.
202	  setInterval(function () {
203	    if (TodoLogic.localToday() !== renderedDay) render();
204	  }, 60000);
205	
206	  render();
207	})();
208	</script>
209	</body>
210	</html>
